import pytest
from candidate import largest_divisor


class TestLargestDivisorNormalCases:
    def test_largest_divisor_of_15_returns_5(self):
        assert largest_divisor(15) == 5

    def test_largest_divisor_of_10_returns_5(self):
        assert largest_divisor(10) == 5

    def test_largest_divisor_of_12_returns_6(self):
        assert largest_divisor(12) == 6

    def test_largest_divisor_of_4_returns_2(self):
        assert largest_divisor(4) == 2

    def test_largest_divisor_of_2_returns_1(self):
        assert largest_divisor(2) == 1

    def test_largest_divisor_of_36_returns_18(self):
        assert largest_divisor(36) == 18

    def test_largest_divisor_of_100_returns_50(self):
        assert largest_divisor(100) == 50

    def test_largest_divisor_of_49_returns_7(self):
        assert largest_divisor(49) == 7


class TestLargestDivisorPrimeNumbers:
    def test_largest_divisor_of_7_returns_1(self):
        assert largest_divisor(7) == 1

    def test_largest_divisor_of_13_returns_1(self):
        assert largest_divisor(13) == 1

    def test_largest_divisor_of_97_returns_1(self):
        assert largest_divisor(97) == 1


class TestLargestDivisorBoundaryConditions:
    def test_largest_divisor_of_1_raises_zero_division_error(self):
        with pytest.raises(ZeroDivisionError):
            largest_divisor(1)

    def test_largest_divisor_of_0_returns_none(self):
        assert largest_divisor(0) is None

    def test_largest_divisor_of_negative_number_returns_none(self):
        assert largest_divisor(-5) is None

    def test_largest_divisor_of_3_returns_1(self):
        assert largest_divisor(3) == 1

    def test_largest_divisor_of_25_returns_5(self):
        assert largest_divisor(25) == 5

    def test_largest_divisor_of_8_returns_4(self):
        assert largest_divisor(8) == 4


class TestLargestDivisorTypeErrors:
    def test_largest_divisor_with_string_raises_type_error(self):
        with pytest.raises(TypeError):
            largest_divisor("15")

    def test_largest_divisor_with_none_raises_type_error(self):
        with pytest.raises(TypeError):
            largest_divisor(None)

    def test_largest_divisor_with_float_raises_type_error(self):
        with pytest.raises(TypeError):
            largest_divisor(15.5)

    def test_largest_divisor_with_list_raises_type_error(self):
        with pytest.raises(TypeError):
            largest_divisor([1, 2, 3])


class TestLargestDivisorEdgeCases:
    def test_largest_divisor_of_perfect_square(self):
        assert largest_divisor(64) == 32

    def test_largest_divisor_of_product_of_two_primes(self):
        assert largest_divisor(77) == 11

    def test_largest_divisor_of_large_number(self):
        assert largest_divisor(1000) == 500

    def test_largest_divisor_returns_int_type(self):
        result = largest_divisor(15)
        assert isinstance(result, int)

    def test_largest_divisor_result_is_less_than_n(self):
        result = largest_divisor(100)
        assert result < 100

    def test_largest_divisor_result_divides_n_evenly(self):
        result = largest_divisor(100)
        assert 100 % result == 0
